<?php
require 'config.php';

// Recupera le impostazioni attuali, inclusa la voce 'logo'
$settings = getSettings(['logo']);
$logo_path = $settings['logo'] ?? 'uploads/default_logo.png'; // Usa un logo predefinito se 'logo' non è impostato

// Se l'utente è già loggato, reindirizza alla dashboard
if (isset($_SESSION['user_id'])) {
    header('Location: ' . $base_url . 'dashboard.php');
    exit;
}

$error = '';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // Verifica del token CSRF
    if (!verifyCsrfToken($_POST['csrf_token'] ?? '')) {
        $error = 'Token CSRF non valido.';
    } else {
        // Recupero dei dati dal form
        $email = sanitizeInput($_POST['email']);
        $password = $_POST['password'];
        $remember_me = isset($_POST['remember_me']) ? true : false;

        // Verifica delle credenziali
        $stmt = executeQuery("SELECT id, username, password, role FROM users WHERE email = ?", [$email], 's');
        if ($stmt) {
            $result = $stmt->get_result();

            if ($result->num_rows === 1) {
                $user = $result->fetch_assoc();
                // Verifica della password
                if (password_verify($password, $user['password'])) {
                    // Credenziali corrette, imposta la sessione
                    $_SESSION['user_id'] = $user['id'];
                    $_SESSION['username'] = $user['username'];
                    $_SESSION['user_role'] = $user['role'];

                    if ($remember_me) {
                        // Imposta il cookie "remember_me" per 30 giorni
                        setcookie('remember_me', '1', time() + (30 * 24 * 60 * 60), '/', '', isset($_SERVER['HTTPS']), true);
                    } else {
                        // Rimuove il cookie "remember_me" se esiste
                        if (isset($_COOKIE['remember_me'])) {
                            setcookie('remember_me', '', time() - 3600, '/', '', isset($_SERVER['HTTPS']), true);
                        }
                    }

                    header('Location: ' . $base_url . 'dashboard.php');
                    exit;
                } else {
                    $error = 'Email o password errati.';
                }
            } else {
                $error = 'Email o password errati.';
            }
        } else {
            $error = 'Errore nella connessione al database.';
        }
    }
}

// Genera un token CSRF per il form
generateCsrfToken();
?>
