    <link href="<?php echo sanitizeForHTML($base_url); ?>theme/vendor/fontawesome-free/css/all.min.css" rel="stylesheet" type="text/css">
    <!-- Google Fonts -->
    <link href="https://fonts.googleapis.com/css2?family=Roboto&display=swap" rel="stylesheet">
    <!-- SB Admin 2 CSS -->
    <link href="<?php echo sanitizeForHTML($base_url); ?>theme/css/sb-admin-2.min.css" rel="stylesheet">
    <!-- Custom CSS -->
    <link href="<?php echo sanitizeForHTML($base_url); ?>styles.css" rel="stylesheet">
</head>

<body class="bg-gradient-primary">

    <div class="container">

        <!-- Outer Row -->
        <div class="row justify-content-center align-items-center min-vh-100">
            <!-- Centrare verticalmente con min-vh-100 -->

            <div class="col-12 col-sm-10 col-md-8 col-lg-6 col-xl-4">
                <!-- Aggiunta di col-12 per extra small, col-sm-10 per piccoli, etc. -->

                <div class="card o-hidden border-0 shadow-lg my-5">
                    <div class="card-body p-0">
                        <!-- Form di Login -->
                        <div class="p-5">
                            <div class="text-center">
                                <img src="<?php echo sanitizeForHTML($base_url . $logo_path); ?>" alt="logo ADL" class="img-fluid mb-4" style="max-width: 150px;">
                                <!-- Aggiunta di img-fluid e margine inferiore -->
                                <h1 class="h4 text-gray-900 mb-4">Benvenuto!</h1>
                            </div>
                            <?php if ($error): ?>
                                <div class="alert alert-danger" role="alert">
                                    <?php echo sanitizeForHTML($error); ?>
                                </div>
                            <?php endif; ?>
                            <form class="user" method="POST" action="<?php echo htmlspecialchars($_SERVER['PHP_SELF']); ?>">
                                <!-- Token CSRF -->
                                <?php csrfInputField(); ?>
                                <div class="form-group">
                                    <input type="email" class="form-control form-control-user" id="email" name="email" aria-describedby="emailHelp" placeholder="Indirizzo Email" required autofocus>
                                </div>
                                <div class="form-group">
                                    <input type="password" class="form-control form-control-user" id="password" name="password" placeholder="Password" required>
                                </div>
                                <div class="form-group">
                                    <div class="custom-control custom-checkbox small">
                                        <input type="checkbox" class="custom-control-input" id="rememberMe" name="remember_me">
                                        <label class="custom-control-label" for="rememberMe">Resta Connesso</label>
                                    </div>
                                </div>
                                <button type="submit" class="btn btn-primary btn-user btn-block">
                                    Accedi
                                </button>
                            </form>
                            <hr>
                            <!-- Opzioni aggiuntive, se necessarie -->
                            <!--
                            <div class="text-center">
                                <a class="small" href="forgot-password.php">Password dimenticata?</a>
                            </div>
                            -->
                        </div>
                    </div>
                </div>

            </div>

        </div>

    </div>

    <!-- Bootstrap core JavaScript-->
